var results = [];
var items = document.querySelectorAll('[data-component-type="s-search-result"]');
items.forEach(function(item) {
  var titleEl = item.querySelector('h2 a');
  var priceEl = item.querySelector('.a-price .a-offscreen');
  // Find the rating element with full format "Rated X out of 5 stars by Y reviews"
  var ratingEl = item.querySelector('a[aria-label*="out of 5 stars by"]');
  var title = titleEl ? (titleEl.getAttribute('aria-label') || titleEl.textContent.trim()) : null;
  var price = priceEl ? priceEl.textContent.trim() : null;
  var ratingLabel = ratingEl ? ratingEl.getAttribute('aria-label') : null;
  var rating = null, reviewCount = null;
  if (ratingLabel) {
    var m = ratingLabel.match(/Rated ([\d.]+) out of 5 stars by ([\d,]+)/);
    if (m) {
      rating = parseFloat(m[1]);
      reviewCount = parseInt(m[2].replace(/,/g, ''));
    }
  }
  results.push({
    title: title,
    price: price,
    rating: rating,
    reviews: reviewCount
  });
});
return results;

var firstItem = document.querySelectorAll('[data-component-type="s-search-result"]')[0];
if (!firstItem) return "no items";
var allInFirst = firstItem.querySelectorAll('a[aria-label], span[aria-label], i[aria-label]');
var out = [];
allInFirst.forEach(function(el) {
  var label = el.getAttribute('aria-label');
  if (label && label.includes('out of 5')) {
    out.push({tag: el.tagName, label: label});
  }
});
return {itemCount: document.querySelectorAll('[data-component-type="s-search-result"]').length, ratingEls: out};

var firstItem = document.querySelectorAll('[data-component-type="s-search-result"]')[0];
if (!firstItem) return "no items";
// Find review count element
var reviewLinks = firstItem.querySelectorAll('a[href*="#customerReviews"], a[href*="customer-review"]');
var out = [];
firstItem.querySelectorAll('*').forEach(function(el) {
  var text = el.textContent && el.textContent.trim();
  if (text && /^\(?(\d+(?:,\d+)*)\)?$/.test(text) && el.children.length === 0) {
    out.push({tag: el.tagName, text: text});
  }
});
return out;

var firstItem = document.querySelectorAll('[data-component-type="s-search-result"]')[0];
