var firstItem = document.querySelectorAll('[data-component-type="s-search-result"]')[0];
// Look at all attributes
var allInfo = {};
['data-asin', 'data-index', 'data-uuid', 'data-component-type'].forEach(function(attr) {
  allInfo[attr] = firstItem.getAttribute(attr);
});
// Get all a links with their hrefs and aria-labels
var allLinks = firstItem.querySelectorAll('a[href*="/dp/"]');
var linkData = [];
allLinks.forEach(function(a) {
  linkData.push({
    href: a.href,
    ariaLabel: a.getAttribute('aria-label'),
    text: a.textContent.trim().substring(0, 100)
  });
});
return {allInfo: allInfo, linkCount: allLinks.length, linkData: linkData};

var results = [];
var items = document.querySelectorAll('[data-component-type="s-search-result"]');
items.forEach(function(item) {
  var titleEl = item.querySelector('h2 a');
  var priceEl = item.querySelector('.a-price .a-offscreen');
  // Find rating element with format "Rated X out of 5 stars by Y reviews"
  var ratingEl = item.querySelector('[aria-label^="Rated"][aria-label*="out of 5"]');
  var title = titleEl ? (titleEl.getAttribute('aria-label') || titleEl.textContent.trim()) : null;
  var price = priceEl ? priceEl.textContent.trim() : null;
  var ratingLabel = ratingEl ? ratingEl.getAttribute('aria-label') : null;
  var rating = null, reviewCount = null;
  if (ratingLabel) {
    var m = ratingLabel.match(/Rated ([\d.]+) out of 5 stars by ([\d,]+)/);
    if (m) {
      rating = parseFloat(m[1]);
      reviewCount = parseInt(m[2].replace(/,/g, ''));
    }
  }
  if (!reviewCount) {
    // Fallback: try the popover ratings
    var popoverEl = item.querySelector('a[aria-label*="ratings"]');
    if (popoverEl) {
      var m2 = popoverEl.getAttribute('aria-label').match(/([\d,]+)/);
      if (m2) reviewCount = parseInt(m2[1].replace(/,/g, ''));
    }
  }
  results.push({
    title: title ? title.substring(0, 100) : null,
    price: price,
    rating: rating,
    reviews: reviewCount
  });
});
return results;

